_CORE_SRC = '# Exact action format: {"moves": [[from_node, to_node, count], ...]}.\n# Payout: "if player_units[i] > opponent_units[i]: you earn demand[i]";\n# if fewer, the opponent earns demand[i]; on a tie, nobody earns.\n# Cost: "MOVE_COST = 0.5" for every unit moved by a legal move.\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 80\nMOVE_COST = 0.5\n\n\ndef payout(own, opponent, demand):\n    """Exact revenue for our player at one node."""\n    return demand if own > opponent else 0\n\n\ndef margin(own, opponent, demand):\n    return payout(own, opponent, demand) - payout(opponent, own, demand)\n\n\ndef preprocess_map(obs):\n    n = int(obs["n_nodes"])\n    adjacency = [[] for _ in range(n)]\n    capacities = {}\n    for edge, capacity in zip(obs["edges"], obs["edge_capacity"]):\n        u, v = map(int, edge)\n        adjacency[u].append(v)\n        adjacency[v].append(u)\n        capacities[min(u, v), max(u, v)] = int(capacity)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n):\n        distance = [n + 1] * n\n        distance[source] = 0\n        queue = deque([source])\n        while queue:\n            u = queue.popleft()\n            for v in adjacency[u]:\n                if distance[v] == n + 1:\n                    distance[v] = distance[u] + 1\n                    queue.append(v)\n        distances.append(distance)\n    return adjacency, capacities, distances\n\n\ndef make_plan(obs, distances, previous_target, deadline):\n    """Transport-aware multiple-choice allocation against stationary opponents.\n\n    Majority payouts are NOT concave: an isolated extra unit can have zero\n    marginal value even though a whole attacking group is profitable. Enumerating\n    all stack sizes in a tiny knapsack avoids the greedy allocator\'s threshold\n    trap, while retaining its marginal-value interpretation.\n    """\n    own = list(obs["player_units"])\n    enemy = obs["opponent_units"]\n    demands = obs["demand"]\n    n = len(own)\n    total = sum(own)\n    remaining = max(0, N_TURNS - int(obs.get("turn", 0)))\n    # Receding-horizon valuation avoids paying for excessively distant conquests.\n    horizon = min(remaining, 18)\n    if not total or not horizon:\n        return own\n\n    options = []\n    for node in range(n):\n        if time.perf_counter() >= deadline:\n            return own\n        travel = sorted(\n            distances[source][node]\n            for source in range(n)\n            for _ in range(own[source])\n        )\n        baseline = margin(0, enemy[node], demands[node])\n        costs = [0.0]\n        for distance in travel:\n            costs.append(costs[-1] + MOVE_COST * distance)\n\n        choices = []\n        for count in range(total + 1):\n            improvement = margin(count, enemy[node], demands[node]) - baseline\n            if count:\n                # The group earns only once enough units have actually arrived.\n                arrival = max(0, travel[count - 1] - 1)\n            else:\n                arrival = 0\n            value = improvement * max(0, horizon - arrival) - costs[count]\n            # Small switching penalty favors already established/sticky groups,\n            # but cannot make an unprofitable remote deployment worthwhile.\n            if previous_target is not None:\n                value -= 0.7 * abs(count - previous_target[node])\n            value -= 0.03 * max(0, count - own[node])\n            choices.append(value)\n        options.append(choices)\n\n    # Unassigned units may remain anywhere for free. All demands are fixed;\n    # no demand forecast is supplied by this game\'s observation.\n    dp = [float("-inf")] * (total + 1)\n    dp[0] = 0.0\n    parents = []\n    for node in range(n):\n        if time.perf_counter() >= deadline:\n            return own\n        next_dp = [float("-inf")] * (total + 1)\n        parent = [None] * (total + 1)\n        for used in range(total + 1):\n            if dp[used] == float("-inf"):\n                continue\n            for count in range(total - used + 1):\n                value = dp[used] + options[node][count]\n                dest = used + count\n                if value > next_dp[dest] + 1e-9:\n                    next_dp[dest] = value\n                    parent[dest] = (used, count)\n        dp = next_dp\n        parents.append(parent)\n\n    used = max(range(total + 1), key=lambda k: (dp[k], -k))\n    target = [0] * n\n    for node in range(n - 1, -1, -1):\n        before, count = parents[node][used]\n        target[node] = count\n        used = before\n    return target\n\n\ndef legal_action(own, target, adjacency, capacities, distances):\n    """Match deficits to surpluses, then replay moves using start-turn units."""\n    n = len(own)\n    surplus = [max(0, own[i] - target[i]) for i in range(n)]\n    deficit = [max(0, target[i] - own[i]) for i in range(n)]\n    pairs = sorted(\n        (distances[s][t], s, t)\n        for s in range(n) if surplus[s]\n        for t in range(n) if deficit[t]\n    )\n    available = list(own)\n    capacity_left = dict(capacities)\n    orders = {}\n\n    for distance, source, destination in pairs:\n        needed = min(surplus[source], deficit[destination])\n        if needed <= 0 or distance <= 0:\n            continue\n        # Split flow between equally short routes when one edge congests.\n        hops = sorted(\n            (v for v in adjacency[source]\n             if distances[v][destination] == distance - 1),\n            key=lambda v: (\n                -capacity_left[min(source, v), max(source, v)], v\n            ),\n        )\n        for hop in hops:\n            edge = (min(source, hop), max(source, hop))\n            count = min(needed, available[source], capacity_left[edge])\n            if count <= 0:\n                continue\n            orders[source, hop] = orders.get((source, hop), 0) + count\n            available[source] -= count\n            capacity_left[edge] -= count\n            surplus[source] -= count\n            deficit[destination] -= count\n            needed -= count\n            if not needed:\n                break\n\n    # Independent final validation; arrivals never enter available.\n    available = list(own)\n    capacity_left = dict(capacities)\n    moves = []\n    for (source, destination), requested in sorted(orders.items()):\n        edge = (min(source, destination), max(source, destination))\n        if edge not in capacity_left or source == destination:\n            continue\n        count = min(requested, available[source], capacity_left[edge])\n        if count > 0:\n            moves.append([int(source), int(destination), int(count)])\n            available[source] -= count\n            capacity_left[edge] -= count\n    return {"moves": moves}\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.previous_target = None\n        self.bad_reports = 0\n        self.conservative = False\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.6 * TIME_BUDGET)\n        if self.map_data is None:\n            self.map_data = preprocess_map(obs)\n        adjacency, capacities, distances = self.map_data\n        own = list(obs["player_units"])\n\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0) > 0):\n            self.bad_reports += 1\n        if self.bad_reports >= 2:\n            self.conservative = True\n\n        if self.conservative or time.perf_counter() >= deadline:\n            return {"moves": []}\n\n        target = make_plan(obs, distances, self.previous_target, deadline)\n        action = legal_action(own, target, adjacency, capacities, distances)\n        self.previous_target = target\n        return action\n'
_CORE_CLASS = 'Strategy'
_FALLBACK_SRC = None
_FALLBACK_CLASS = 'Strategy'
_ACT_LIMIT_S = 0.7
